// bktec fetches and runs test plans generated by Buildkite
// Test Engine.
package main

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"

	"github.com/buildkite/test-engine-client/v3/internal/command"
	"github.com/buildkite/test-engine-client/v3/internal/config"
	"github.com/buildkite/test-engine-client/v3/internal/debug"
	"github.com/buildkite/test-engine-client/v3/internal/git"
	"github.com/buildkite/test-engine-client/v3/internal/runnerexec"
	"github.com/buildkite/test-engine-client/v3/internal/version"
	"github.com/urfave/cli/v3"
)

var cfg = config.New()

func main() {
	if err := cliCommand.Run(context.Background(), os.Args); err != nil {
		logErrorAndExit(err)
	}
}

func run(ctx context.Context, cmd *cli.Command) error {
	debug.SetDebug(cmd.Bool("debug"))

	if err := applyPlanRequestContext(cmd); err != nil {
		return err
	}

	if err := cfg.ValidateForRun(); err != nil {
		return fmt.Errorf("bktec run: invalid configuration:\n%w", err)
	}

	return command.Run(ctx, &cfg, cmd.String("files"))
}

func plan(ctx context.Context, cmd *cli.Command) error {
	debug.SetDebug(cmd.Bool("debug"))
	debug.SetOutput(os.Stderr)

	if err := applyPlanRequestContext(cmd); err != nil {
		return err
	}

	if err := cfg.ValidateForPlan(); err != nil {
		return fmt.Errorf("bktec plan: invalid configuration:\n%w", err)
	}

	switch {
	case cmd.Bool("json"):
		return command.Plan(ctx, &cfg, cmd.String("files"), command.PlanOutputJSON, "")
	case cmd.IsSet("plan-out"):
		return command.Plan(ctx, &cfg, cmd.String("files"), command.PlanOutputPlanOut, "")
	default:
		return command.Plan(ctx, &cfg, cmd.String("files"), command.PlanOutputPipelineUpload, cmd.String("pipeline-upload"))
	}
}

func poolPlan(ctx context.Context, cmd *cli.Command) error {
	debug.SetDebug(cmd.Root().Bool("debug"))
	debug.SetOutput(os.Stderr)
	if err := applyPlanRequestContext(cmd); err != nil {
		return err
	}
	if cfg.PoolID != "" {
		return fmt.Errorf("bktec pool plan: --pool-id / BUILDKITE_TEST_ENGINE_POOL_ID is for pool exec; omit it to plan a pool")
	}
	if err := cfg.ValidateForPoolPlan(); err != nil {
		return fmt.Errorf("bktec pool plan: invalid configuration:\n%w", err)
	}
	output := command.PlanOutputJSON
	if cmd.IsSet("pipeline-upload") {
		output = command.PlanOutputPipelineUpload
	}
	return command.PoolPlan(ctx, &cfg, cmd.String("files"), output, cmd.String("pipeline-upload"))
}

func poolExec(ctx context.Context, cmd *cli.Command) error {
	if cmd.Args().Len() == 0 {
		return fmt.Errorf("pool exec requires -- <persistent-runner> [arguments...]")
	}
	if cmd.Int("local-retry-count") < 0 {
		return fmt.Errorf("local-retry-count must not be negative")
	}
	opts := runnerexec.Options{StartupTimeout: cmd.Duration("runner-startup-timeout"), BatchTimeout: cmd.Duration("runner-batch-timeout"), ShutdownTimeout: cmd.Duration("runner-shutdown-timeout")}
	if opts.StartupTimeout <= 0 || opts.BatchTimeout <= 0 || opts.ShutdownTimeout <= 0 {
		return fmt.Errorf("runner timeouts must be positive")
	}
	debug.SetDebug(cmd.Root().Bool("debug"))
	debug.SetOutput(os.Stderr)
	if err := applyPlanRequestContext(cmd); err != nil {
		return err
	}
	if err := cfg.ValidateForPoolPlan(); err != nil {
		return fmt.Errorf("bktec pool exec: invalid configuration: %w", err)
	}
	return command.PoolExec(ctx, &cfg, cmd.String("files"), cmd.Args().Slice(), cmd.Int("local-retry-count"), opts)
}

func backfillCommitMetadata(ctx context.Context, cmd *cli.Command) error {
	debug.SetDebug(cmd.Root().Bool("debug"))
	debug.SetOutput(os.Stderr)

	if err := cfg.ValidateForBackfillCommitMetadata(); err != nil {
		return fmt.Errorf("bktec tools backfill-commit-metadata: invalid configuration:\n%w", err)
	}

	return command.BackfillCommitMetadata(ctx, &cfg, &git.ExecGitRunner{})
}

func printVersion(ctx context.Context, cmd *cli.Command, versionFlag bool) error {
	// Flag will be true if called with `bktec [...] --version`
	if !versionFlag {
		return nil
	}
	fmt.Printf("bktec %s\n", version.Version)
	os.Exit(0)
	return nil
}

func logErrorAndExit(err error) {
	fmt.Fprintln(os.Stderr, err)

	exitError := new(exec.ExitError)
	if errors.As(err, &exitError) {
		// If error wraps an exitError exit with the specified code ...
		os.Exit(exitError.ExitCode())
	} else {
		// otherwise exit code 16
		os.Exit(16)
	}
}
